CREATE TABLE IF NOT EXISTS relay_channels(id INT AUTO_INCREMENT PRIMARY KEY,guild_id VARCHAR(32) UNIQUE NOT NULL,channel_id VARCHAR(32) NOT NULL);
CREATE TABLE IF NOT EXISTS voice_channels(id INT AUTO_INCREMENT PRIMARY KEY,guild_id VARCHAR(32) UNIQUE NOT NULL,channel_id VARCHAR(32) NOT NULL);
CREATE TABLE IF NOT EXISTS bans(id INT AUTO_INCREMENT PRIMARY KEY,user_id VARCHAR(32) UNIQUE NOT NULL,reason TEXT,expires_at DATETIME NULL,active BOOLEAN DEFAULT TRUE,moderator_id VARCHAR(32));
CREATE TABLE IF NOT EXISTS vip(id INT AUTO_INCREMENT PRIMARY KEY,user_id VARCHAR(32) UNIQUE NOT NULL,level INT DEFAULT 1,price_rub INT DEFAULT 1999);
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,user_id VARCHAR(32) UNIQUE NOT NULL,level INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS server_bans(id INT AUTO_INCREMENT PRIMARY KEY,guild_id VARCHAR(32) UNIQUE NOT NULL,reason TEXT,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS moderation_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id VARCHAR(32),moderator_id VARCHAR(32),action VARCHAR(32),reason TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages(id INT AUTO_INCREMENT PRIMARY KEY,guild_id VARCHAR(32),channel_id VARCHAR(32),user_id VARCHAR(32),username VARCHAR(100),content TEXT,message_id VARCHAR(64),reply_id VARCHAR(64),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);